n_agentd_Server_attachCardBaseBranches.signature:
// attachCardBaseBranches 在 Git 工作树已经成功后，按请求顺序逐张设置卡基线。
// 单张失败只进入该项结果，不删除已经存在的工作树，也不回滚此前成功的卡。
func (s *Server) attachCardBaseBranches(ws proto.Workspace, ids []string, actor string) proto.Workspace {
	results := make([]proto.CardBaseBranchResult, 0, len(ids))
	s.log.Info("建树后开始逐卡挂基线", "branch", ws.Branch, "card_count", len(ids), "actor", actor)
	for _, id := range ids {
		result := proto.CardBaseBranchResult{ID: id}
		if err := s.ledger.SetCardBaseBranch(id, ws.Branch, actor); err != nil {
			result.Error = err.Error()
			s.log.Warn("建树后挂卡失败：工作树保留", "card", id, "branch", ws.Branch, "cause", err)
		} else {
			result.OK = true
			s.log.Info("建树后挂卡完成", "card", id, "branch", ws.Branch, "actor", actor)
		}
		results = append(results, result)
	}
	ws.CardResults = results
	s.log.Info("建树后逐卡挂基线完成", "branch", ws.Branch, "card_count", len(results))
	return ws
}

n_agentd_Server_byTask.signature:
// byTask 包住 /api/tasks/{id}/... 系列 handler，按任务归属决定本机处理还是转发。
//
// 注意：render 是流式响应，也走同一条搬运——forwardTo 用 io.Copy 直通，
// 客户端断开时 r.Context() 取消、上游连接随之断开，无需特殊处理。
func (s *Server) byTask(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")
		if id == "" || isForwarded(r) {
			next(w, r)
			return
		}
		if s.mgr == nil {
			s.log.Warn("任务路由：manager 未注入", "task", id)
			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
			return
		}
		if _, err := s.mgr.GetTask(id); err == nil {
			next(w, r) // 本机的活
			return
		} else if !errors.Is(err, store.ErrNotFound) {
			s.log.Error("任务路由：查本机任务失败", "task", id, "cause", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
			return
		}
		target, ok, err := s.mgr.MirrorTaskTarget(id)
		if err != nil {
			s.log.Error("任务路由：查镜像索引失败", "task", id, "cause", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
			return
		}
		if !ok {
			next(w, r) // 两处都没有：让 handler 给出与今天一致的 404
			return
		}
		t, defined := s.conf().Targets[target]
		if !defined {
			// 镜像里记着一台配置里已经没有的机器：如实报告，别假装 404
			s.log.Warn("任务路由：镜像指向的机器已不在配置中",
				"task", id, "machine", target)
			writeJSON(w, http.StatusBadGateway, map[string]string{
				"error": "任务在机器 " + target + " 上，但它已不在本机配置的 targets 中"})
			return
		}
		// relay 机器没有 addr，传输必须复用池里的选路结果（与各扇出同一条纪律）
		c, err := s.pool.For(target)
		if err != nil {
			s.log.Error("任务路由：取目标客户端失败", "task", id, "machine", target, "cause", err)
			writeJSON(w, http.StatusBadGateway, map[string]string{
				"error": "转发到 " + target + " 失败: " + err.Error()})
			return
		}
		s.log.Info("任务路由：转发到远端", "task", id, "machine", target,
			"method", r.Method, "path", r.URL.Path)
		s.forwardTo(w, r, target, c, t.Token)
	}
}

