		for _, task := range tasks {
			localTasks[task.ID] = task
		}
		s.log.Debug("本机 attach 任务索引已就绪", "tasks", len(localTasks))
		break
	}

	for i := range rooms {
		if rooms[i].Kind != room.KindCard {
			continue
		}
		roomLinks := linksByRoom[rooms[i].ID]
		if len(roomLinks) == 0 {
			continue
		}
		for linkIndex := len(roomLinks) - 1; linkIndex >= 0; linkIndex-- {
			link := roomLinks[linkIndex]
			if link.Target == "" {
				attach, lookupErr := s.lookupRoomAttach(context.Background(), link, localTasks)
				if lookupErr != nil {
					s.log.Warn("房间 attach 本机任务不可解析", "room", rooms[i].ID,
						"task", link.TaskID, "cause", lookupErr)
					continue
				}
				rooms[i].Attach = attach
				s.log.Info("房间 attach 投影成功", "room", rooms[i].ID,
					"target", link.Target, "task", link.TaskID, "workdir", attach.WorkDir)
				break
			}
			if attach := s.cachedRoomAttach(link); attach != nil {
				rooms[i].Attach = attach
				s.log.Info("房间 attach 从缓存投影成功", "room", rooms[i].ID,
					"target", link.Target, "task", link.TaskID, "workdir", attach.WorkDir)
				break
			}
		}
	}
	s.startRoomAttachRefresh(links)
	s.log.Info("房间 attach 投影完成", "rooms", len(rooms), "links", len(links))
}

n_agentd_Server_handleContinue.signature:
// handleContinue 向任务续发修改指令（要求任务处于 waiting_review）。
//
// 错误映射：任务不存在 404；状态不允许续接 409（manager 返回 store.ErrBadTransit）；
// executor 运行态已丢失 409（executor.ErrTaskNotRunning，agentd 可能重启过，提示
// 重新派发）。
func (s *Server) handleContinue(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("continue 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	if s.mgr == nil {
		s.log.Warn("continue 请求到达但 manager 未注入", "task", taskID)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var req continueRequest
	if err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		s.log.Warn("continue 请求体解析失败", "task", taskID, "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON {instructions}"})
		return
	}
	if req.Instructions == "" {
		s.log.Warn("continue 指令为空", "task", taskID)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "instructions 不能为空"})
		return
	}
	if err := s.mgr.Continue(r.Context(), taskID, req.Instructions); err != nil {
		s.writeManagerError(w, taskID, "续发指令", err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
}

n_agentd_Server_handleCoordAttach.signature:
// handleCoordAttach POST /api/cards/{id}/attach：attach 深聊的接管/交回同一端点
// （配对原语表：SetAttach true 与 false 都在本端点）。
//
// active=true：先置接管再定位（缺口期宁可占用不可唤醒）；定位失败回滚接管态并 400。
// active=false：交回无头，自动唤醒恢复。
func (s *Server) handleCoordAttach(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) { // 跨机 ?machine= 转发（契约 §11）
		return
	}
	id := r.PathValue("id")
	s.log.Info("处理协调者 attach", "card", id)
	var body struct {
		Active  *bool  `json:"active"`
		Workdir string `json:"workdir"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeErr(w, http.StatusBadRequest, fmt.Errorf("解析请求体: %w", err))
		return
	}
	if body.Active == nil {
		s.log.Warn("协调者 attach 请求缺少 active", "card", id, "reason", "active_missing")
		writeErr(w, http.StatusBadRequest, fmt.Errorf("active 必填（true=接管，false=交回无头）"))
		return
	}
	if _, err := s.ledger.GetCard(id); err != nil {
		ledgerErr(w, err)
		return
	}
	if *body.Active {
		s.log.Info("协调者 attach 定位开始", "card", id, "workdir", body.Workdir)
		s.keystone.SetAttach(id, true)
		info, err := s.keystone.Locate(id, body.Workdir)
		if err != nil {
			s.keystone.SetAttach(id, false) // 回滚：没有终端可接管，不得留下静默占用
			s.log.Warn("attach 定位失败，接管态已回滚", "card", id, "workdir", body.Workdir, "cause", err)
			writeErr(w, http.StatusBadRequest, err)
			return
		}
		mapped := coordinatorAttachInfo(info)
		// command 只返回给请求方，不写日志：它包含 resume session id。
		s.log.Info("attach 接管完成", "card", id, "machine", mapped.Machine, "dir", mapped.Dir)
		writeJSON(w, http.StatusOK, mapped)
		return
	}
	s.keystone.SetAttach(id, false)
	s.log.Info("attach 交回", "card", id)
	writeJSON(w, http.StatusOK, proto.CoordinatorAttachReleaseResp{OK: true})
}

n_agentd_Server_handleCoordStatus.signature:
func (s *Server) handleCoordStatus(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	s.log.Info("读取协调者状态", "card", id)
	card, err := s.ledger.GetCard(id)
	if err != nil {
		ledgerErr(w, err)
		return
	}
	validSeat := card.DriverSession != "" && proto.ValidateSeat(card.DriverSession, proto.SeatSource(card.DriverSource)) == nil
	active := s.keystone.AttachState(id)
	var attach *proto.CoordinatorAttachInfo
	workdir := s.resolveCoordWorkdir(id)
	if info, err := s.keystone.Locate(id, workdir); err != nil {
		s.log.Warn("协调者状态定位失败", "card", id, "workdir", workdir, "cause", err)
	} else {
		mapped := coordinatorAttachInfo(info)
		attach = &mapped
		s.log.Info("协调者状态已读", "card", id, "bound", validSeat,
			"attach_active", active, "dir", mapped.Dir)
	}
	if attach == nil {
		s.log.Info("协调者状态已读", "card", id, "bound", false, "attach_active", active)
	}
	writeJSON(w, http.StatusOK, proto.CoordinatorStatus{Bound: validSeat, AttachActive: active, Attach: attach})
}

n_agentd_Server_handleDispatch.signature:
// handleDispatch 派发一个新任务，返回创建后的任务（state=running）。
//
// 流程：解析请求体 → 冻结身份准入或普通接收者准备链 → 接收机必须是载体登记机
// → manager.Dispatch（建任务/写 plan/启动 executor/进 running）。带 Carrier 的
// 请求必须使用已冻结的物理身份；Receiver 只作为审计字段，不能再次选择载体。
func (s *Server) handleDispatch(w http.ResponseWriter, r *http.Request) {
	s.log.Info("dispatch 请求", "method", r.Method, "path", r.URL.Path,
		"remote_addr", r.RemoteAddr)
	if s.mgr == nil {
		s.log.Warn("dispatch 请求到达但 manager 未注入", "remote_addr", r.RemoteAddr)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var req dispatchRequest
	if err := json.NewDecoder(io.LimitReader(r.Body, 4<<20)).Decode(&req); err != nil {
		s.log.Warn("dispatch 请求体解析失败", "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON {project_id, plan_b64, ...}"})
		return
	}
	s.log.Info("dispatch 请求身份", "project", req.ProjectID, "receiver", req.Receiver,
		"carrier", req.Carrier, "squad", req.Squad, "target", req.Target,
		"executor", req.Executor, "model", req.Model, "home_dir_set", req.HomeDir != nil)
	var binding scheduling.Binding
	var resolved scheduling.ResolvedReceiver
	var err error
	if req.Carrier != "" {
		if s.scheduling == nil {
			err = errors.New("编制域服务未装配（SetupAutomation 未执行）")
		} else if req.HomeDir == nil {
			err = fmt.Errorf("%w: 冻结请求必须明确携带 home_dir（空串表示目标机主 HOME）", scheduling.ErrInvalid)
			s.log.Warn("dispatch 冻结身份缺少 home_dir", "project", req.ProjectID,
				"receiver", req.Receiver, "carrier", req.Carrier, "squad", req.Squad,
				"target", req.Target, "error_kind", "frozen_home_dir_missing", "cause", err)
		} else {
			homeDir := *req.HomeDir
			binding, err = s.scheduling.AdmitFrozen(scheduling.Binding{
				Squad: req.Squad, Carrier: req.Carrier, Target: req.Target,
				Executor: req.Executor, Model: req.Model, HomeDir: homeDir,
			})
			s.log.Info("dispatch 冻结身份准入", "project", req.ProjectID, "receiver", req.Receiver,
				"carrier", req.Carrier, "squad", req.Squad, "target", req.Target,
				"executor", req.Executor, "model", req.Model, "error_kind", "frozen_admit")
		}
	} else if req.Squad != "" {
		err = fmt.Errorf("%w: 冻结小队请求缺少 carrier", scheduling.ErrInvalid)
	} else {
		overlay := scheduling.PhysicalOverlay{Machine: req.Target, CLI: req.Executor, HomeDir: req.HomeDir}
		binding, resolved, err = s.prepareReceiverBinding(req.Receiver, overlay, req.Model)
		s.log.Info("dispatch 普通身份准入", "project", req.ProjectID, "receiver", req.Receiver,
			"resolved_name", resolved.Name, "resolved_kind", string(resolved.Kind),
			"carrier", binding.Carrier, "squad", binding.Squad, "target", binding.Target,
			"executor", binding.Executor, "model", binding.Model, "error_kind", "ordinary_admit")
	}
	if err != nil {
		s.log.Warn("dispatch 身份准入失败", "project", req.ProjectID, "receiver", req.Receiver,
			"carrier", req.Carrier, "squad", req.Squad, "target", req.Target,
			"error_kind", "admit", "cause", err)
		s.writeDispatchError(w, req.ProjectID, err)
		return
	}
	released := false
	defer func() {
		if !released && binding.Carrier != "" && s.scheduling != nil {
			if relErr := s.scheduling.Release(binding.Squad, binding.Carrier); relErr != nil {
				s.log.Error("dispatch 失败释放占用失败", "project", req.ProjectID,
					"squad", binding.Squad, "carrier", binding.Carrier, "cause", relErr)
			}
		}
	}()
	home := binding.HomeDir
	var homePtr *string
	if req.Carrier != "" || home != "" {
		homePtr = &home
	}
	s.log.Info("dispatch 任务身份快照已组装", "project", req.ProjectID,
		"carrier", binding.Carrier, "squad", binding.Squad, "target", binding.Target,
		"executor", binding.Executor, "home_dir_set", homePtr != nil)
	// B233.27：准入只核「请求 vs 登记」。现网登记名常是 targets 键（linux-01），
	// 不能只用 IsLocalMachine（它把 linux-01 当远端）。CanonicalTarget 空串=本机。
	if canon := s.CanonicalTarget(binding.Target); canon != "" {
		err = fmt.Errorf("%w: 载体登记机 %s 不是当前接收机", errReceiverNotCarrierMachine, binding.Target)
		s.log.Warn("dispatch 被拒：接收机不是载体登记机", "project", req.ProjectID,
			"carrier", binding.Carrier, "registered_target", binding.Target,
			"canonical_target", canon, "error_kind", "receiver_not_carrier_machine", "cause", err)
		s.writeDispatchError(w, req.ProjectID, err)
		return
	}
	task, err := s.mgr.Dispatch(r.Context(), orchestration.DispatchReq{
		ProjectID: req.ProjectID, ProjectName: req.ProjectName,
		PlanB64: req.PlanB64, PlanName: req.PlanName, Target: binding.Target,
		Prompt: req.Prompt, Name: req.Name, Receiver: req.Receiver, Squad: binding.Squad, Carrier: binding.Carrier,
		Executor: binding.Executor, Discipline: req.Discipline, Model: binding.Model,
		HomeDir:           homePtr,
		DisciplineText:    req.DisciplineText,
		DisciplineVersion: req.DisciplineVersion,
		Branch:            req.Branch, NewBranch: req.NewBranch, Base: req.Base,
		ResolveDefaultBase: req.ResolveDefaultBase,
		LocalBaseBranch:    req.LocalBaseBranch,
		Worktree:           req.Worktree, NewWorktree: req.NewWorktree, BaseCommit: req.BaseCommit,
	})
	if err != nil {
		s.writeDispatchError(w, req.ProjectID, err)
		return
	}
	released = true // 成功后由 T4 的任务终态钩子释放占用
	s.log.Info("dispatch 完成", "task", task.ID, "state", task.State, "carrier", task.Carrier,
		"squad", binding.Squad, "target", binding.Target, "executor", binding.Executor)
	writeJSON(w, http.StatusOK, task)
}

n_agentd_Server_handleDone.signature:
// handleDone 归档任务（要求任务处于 waiting_review）：置 completed 并回收 executor。
func (s *Server) handleDone(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("done 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	if s.mgr == nil {
		s.log.Warn("done 请求到达但 manager 未注入", "task", taskID)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	// body 缺失或非法一律按「无说明」处理，不报错（见 doneRequest 注释）
	var req doneRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil && !errors.Is(err, io.EOF) {
		s.log.Debug("done 请求体解析失败，按无说明处理", "task", taskID, "cause", err)
		req.Note = ""
	}
	if len(req.Note) > proto.MaxDoneNoteBytes {
		s.log.Warn("归档说明超长被拒", "task", taskID,
			"note_bytes", len(req.Note), "limit", proto.MaxDoneNoteBytes)
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("归档说明超长（%d 字节，上限 %d）", len(req.Note), proto.MaxDoneNoteBytes)})
		return
	}
	// done 幂等：agentd 被压垮时（B93 事故），第一次 done 的请求已落库但响应
	// 读超时，审核者的自然反应是重发，而重发拿到的 409 看起来像「状态不对」。
	// 客户端分不清「超时 = 请求没到」和「超时 = 请求到了但响应没回来」——
	// 这是只有服务端才有的信息，只能在这里解决。
	//
	// **判据要严**：只有 completed 转 200。其余非 waiting_review 的状态仍然
	// 409——那些是真的状态不对，一并放行等于让 done 变成万能收口，审核者会
	// 失去「我操作错了」这个信号。
	if cur, err := s.mgr.GetTask(taskID); err == nil && cur.State == proto.TaskStateCompleted {
		s.log.Info("done 已幂等完成，跳过重复释放", "task", taskID, "state", cur.State,
			"carrier", cur.Carrier, "squad", cur.Squad, "error_kind", "already_completed")
		writeJSON(w, http.StatusOK, doneResult{OK: true, NoteSaved: req.Note != ""})
		return
	}
	cur, taskErr := s.mgr.GetTask(taskID)
	if taskErr != nil {
		s.log.Error("done 读取任务快照失败，未执行终态迁移", "task", taskID, "cause", taskErr)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "读取任务快照失败"})
		return
	}
	outcome, err := s.mgr.Done(r.Context(), taskID, req.Note)
	if err != nil {
		s.writeManagerError(w, taskID, "归档任务", err)
		return
	}
	if !outcome.Claimed {
		// 并发 loser / 幂等重发：迁移与释放由赢家承担，本条 200 但不释放。
		s.log.Info("done 幂等成功，跳过占用释放", "task", taskID)
		writeJSON(w, http.StatusOK, doneResult{OK: true, NoteSaved: req.Note != ""})
		return
	}
	terminal, snapshotErr := s.mgr.GetTask(taskID)
	if snapshotErr != nil {
		// 任务身份在终态迁移中不会改变；读回失败时用迁移前已取得的
		// 同一身份快照补释放，避免“不能确认快照”变成容量泄漏。
		s.log.Error("done 成功后读取终态任务快照失败，使用迁移前身份快照释放占用",
			"task", taskID, "cause", snapshotErr)
		s.releaseTaskCarrierOccupancy(cur)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "任务已归档但读取终态快照失败"})
		return
	}
	s.releaseTaskCarrierOccupancy(terminal)
	// 消息文字必须与 manager.Done 的「done 完成」区分开：两处同名会让一次归档
	// 捞出两行日志，其中一行没有 note_saved，排障时分不清看的是哪一层
	s.log.Info("done 请求完成", "task", taskID, "note_saved", req.Note != "")
	writeJSON(w, http.StatusOK, doneResult{OK: true, NoteSaved: req.Note != ""})
}

