n_agentd_Server_handleStop.signature:
// handleStop 主动中止任务（停 executor、落 failed；作废由终态迁移收口完成）。
//
// 响应体：status=stopped；worktree_removed 是兼容字段，成功 Stop 恒为 false。
// Stop 只落 failed 并留存现场，显式 reclaim/gc 才清理 managed worktree；用户自带
// worktree / 原地模式同样返回 false。CLI 据此打印提示文案，不猜。
//
// 错误映射：任务不存在 404；已是终态 409（manager 返回 store.ErrBadTransit）。
func (s *Server) handleStop(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("stop 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	if s.mgr == nil {
		s.log.Warn("stop 请求到达但 manager 未注入", "remote_addr", r.RemoteAddr)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	task, taskErr := s.mgr.GetTask(taskID)
	if taskErr != nil {
		s.log.Error("stop 读取任务快照失败，未执行终态迁移", "task", taskID, "cause", taskErr)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "读取任务快照失败"})
		return
	}
	outcome, err := s.mgr.Stop(r.Context(), taskID)
	if err != nil {
		s.writeManagerError(w, taskID, "stop", err)
		return
	}
	if !outcome.Claimed {
		// 并发 loser：任务已被他人终结，按 409 语义返回（Manager.Stop 已返回 ErrBadTransit）。
		s.log.Warn("stop 并发竞争失败，任务已被终结", "task", taskID)
		writeJSON(w, http.StatusConflict, map[string]string{"error": "任务已是终态"})
		return
	}
	terminal, snapshotErr := s.mgr.GetTask(taskID)
	if snapshotErr != nil {
		// 与 Done 同理：终态迁移不改任务身份，保留一次可释放的快照，
		// 同时把快照读取故障明确返回给调用方。
		s.log.Error("stop 成功后读取终态任务快照失败，使用迁移前身份快照释放占用",
			"task", taskID, "cause", snapshotErr)
		s.releaseTaskCarrierOccupancy(task)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "任务已停止但读取终态快照失败"})
		return
	}
	s.releaseTaskCarrierOccupancy(terminal)
	writeJSON(w, http.StatusOK, map[string]any{"status": "stopped", "worktree_removed": outcome.WorktreeRemoved})
}

