n_agentd_Server_handleTaskRun.signature:
// handleTaskRun 在任务仓库执行一条审阅命令（sh -c），返回合并输出与退出码。
//
// 注意：这是协调者主动发起的只读审阅动作（跑测试/lint），**不走审批门**——
// 命令由协调者指定并经 sh 执行，agentd 只负责执行、限时（10min 超时被杀，退出码
// 124）与回收。命令非零退出同样返回 200，退出码在响应体中表达。
func (s *Server) handleTaskRun(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("run 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	repo, ok := s.taskRepoOrErr(w, taskID)
	if !ok {
		return
	}
	var req runRequest
	// LimitReader 限制请求体大小，防止恶意大 body 占满内存
	if err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		s.log.Warn("run 请求体解析失败", "task", taskID, "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON {cmd}"})
		return
	}
	if strings.TrimSpace(req.Cmd) == "" {
		s.log.Warn("run 命令为空", "task", taskID)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "cmd 不能为空"})
		return
	}
	stdout, exitCode, err := workspace.RunCmd(r.Context(), repo, req.Cmd)
	if err != nil {
		if errors.Is(err, orchestration.ErrNoProcHeadroom) || errors.Is(err, workspace.ErrWorkdirGone) {
			s.log.Warn("run 被拒", "task", taskID, "repo", repo,
				"cmd", truncateRunes(req.Cmd, 200), "cause", err)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": truncateRunes(err.Error(), 200)})
			return
		}
		s.log.Error("run 执行失败", "task", taskID, "cmd", truncateRunes(req.Cmd, 200), "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	writeJSON(w, http.StatusOK, runResponse{Stdout: stdout, ExitCode: exitCode})
}

n_agentd_Server_handleWorkspaceDir.signature:
// handleWorkspaceDir 处理 GET /api/workspaces/dir?path=&rel=[&machine=]。
//
// 参数：
//   - path: 工作树绝对路径（必须，且必须命中白名单，否则 400）
//   - rel: 工作树内的相对目录路径；省略或空串表示工作树根
//   - machine: 可选，转发到指定机器（复用 forwardIfRequested）
func (s *Server) handleWorkspaceDir(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	rel := r.URL.Query().Get("rel")
	s.log.Info("工作树目录列举请求", "path", r.URL.Query().Get("path"), "rel", rel)
	root, ok := s.workspaceRootOrErr(w, r)
	if !ok {
		return
	}
	entries, err := workspace.ListDir(root, rel)
	if err != nil {
		switch {
		case errors.Is(err, workspace.ErrPathEscape):
			s.log.Warn("目录列举路径逃逸被拒绝", "root", root, "rel", rel)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "路径不合法（不允许逃出工作树）"})
		case errors.Is(err, fs.ErrNotExist):
			s.log.Warn("目录列举目标不存在", "root", root, "rel", rel)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "目录不存在"})
		case errors.Is(err, workspace.ErrPathNotDir):
			s.log.Warn("目录列举目标不是目录", "root", root, "rel", rel)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "路径不是目录"})
		default:
			s.log.Error("目录列举失败", "root", root, "rel", rel, "cause", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "目录列举失败"})
		}
		return
	}
	// 忽略标注在列举之后单独做：ListDir 是纯文件系统操作（还被建/删/改名复用），
	// 而「归不归 git 管」要问 git。失败只降级不影响这次列举（见 markIgnored）
	workspace.MarkIgnored(r.Context(), root, rel, entries)
	s.log.Info("工作树目录列举完成", "root", root, "rel", rel, "entries", len(entries))
	writeJSON(w, http.StatusOK, proto.DirListResult{Entries: entries})
}

