n_agentd_Server_lookupRoomAttach.signature:
// lookupRoomAttach 只接受真实任务详情和 Workdir()；不从 bound_session 猜测 task。
// localTasks 是列表装配点的一次性本机任务索引，避免逐挂账查询。
func (s *Server) lookupRoomAttach(ctx context.Context, link ledger.TaskLink, localTasks map[string]proto.Task) (*proto.RoomAttach, error) {
	var workDir string
	if link.Target == "" {
		task, ok := localTasks[link.TaskID]
		if !ok {
			return nil, fmt.Errorf("读取本机任务 %s: 任务不存在", link.TaskID)
		}
		workDir = task.Workdir()
	} else {
		peer, err := s.pool.For(link.Target)
		if err != nil {
			return nil, fmt.Errorf("获取 target %s 客户端: %w", link.Target, err)
		}
		info, err := peer.Attach(ctx, link.TaskID)
		if err != nil {
			return nil, fmt.Errorf("读取远端任务 %s: %w", link.TaskID, err)
		}
		workDir = info.Task.Workdir()
	}
	if strings.TrimSpace(workDir) == "" {
		return nil, errors.New("任务没有可用工作目录")
	}
	return &proto.RoomAttach{
		Target: link.Target, TaskID: link.TaskID, WorkDir: workDir,
		Command: "handoff attach " + link.TaskID,
	}, nil
}

n_agentd_Server_releaseTaskCarrierOccupa.signature:
// releaseTaskCarrierOccupancy 释放任务快照持有的载体与小队成员占用。
// Squad 与 Carrier 都在 CreateTask 时冻结；空 Squad 仍会由 OccupancyKeys 省略成员键，
// 从而让载体直派和旧任务保持只释放载体位的语义。
func (s *Server) releaseTaskCarrierOccupancy(task *proto.Task) {
	if task == nil {
		s.log.Warn("任务终态没有任务快照可释放", "error_kind", "task_missing")
		return
	}
	memberKey := scheduling.OccupancyMemberKey(task.Squad, task.Carrier)
	carrierKey := scheduling.OccupancyCarrierKey(task.Carrier)
	if task.Carrier == "" {
		s.log.Info("任务终态无载体占用可释放", "task", task.ID, "state", task.State,
			"squad", task.Squad, "carrier", task.Carrier, "member_key", memberKey,
			"carrier_key", carrierKey, "error_kind", "no_carrier")
		return
	}
	if s.scheduling == nil {
		s.log.Error("任务终态释放占用失败：编制域未装配", "task", task.ID, "state", task.State,
			"squad", task.Squad, "carrier", task.Carrier, "member_key", memberKey,
			"carrier_key", carrierKey, "error_kind", "scheduling_unavailable")
		return
	}
	if err := s.scheduling.Release(task.Squad, task.Carrier); err != nil {
		s.log.Error("任务终态释放载体占用失败", "task", task.ID, "state", task.State,
			"squad", task.Squad, "carrier", task.Carrier, "member_key", memberKey,
			"carrier_key", carrierKey, "error_kind", "release", "cause", err)
		return
	}
	s.log.Info("任务终态已释放载体占用", "task", task.ID, "state", task.State,
		"squad", task.Squad, "carrier", task.Carrier, "member_key", memberKey,
		"carrier_key", carrierKey, "owner", "task_terminal", "error_kind", "release_success")
}

