n_agentd_Server_resolveWorkspace.signature:
// resolveWorkspace 判定 path 是否是本机**已探测到**的某个工作树。
//
// 判定口径与 GET /api/projects/tree 完全一致：先比登记表里的位置路径（一次
// 数据库读，绝大多数请求命中主目录时到此为止），未命中再对每个 location 跑一次
// git worktree list 现场探测。两段式是为了让最常见的请求不付探测成本。
//
// 为什么不缓存探测结果：worktree 会在 agentd 背后被 git worktree add/remove
// 改动，缓存必然产生「已经删掉的工作树还能浏览」的失真窗口——而这条闸门是
// **参数校验**，失真窗口会让用户浏览到一个已经不存在的工作树，报错莫名其妙。
// 真变慢了再谈带短 TTL 的缓存。
//
// 参数：
//   - ctx: 上下文，透传给 probeWorkspaces（其内部另有 5s 兜底超时）
//   - path: 调用方上送的工作树绝对路径
//
// 返回：
//   - 归一化（filepath.Clean）后的路径，仅在 ok 为真时有意义
//   - ok: 命中白名单为真
func (s *Server) resolveWorkspace(ctx context.Context, path string) (string, bool) {
	want := filepath.Clean(path)
	// 草稿区是这道闸门的第二个入口。它不是 git 工作树，也不在 project_locations
	// 表里，所以下面按登记表比对与现场探测两段都命中不了它（spec §5.1）。
	//
	// 放在最前面短路：这是一次纯字符串比较，比读一次数据库便宜；而草稿区的请求
	// 频率与工作树同量级（浮窗里每存一次就是一次 PUT）。
	//
	// 只放行它**自己**，不放行父目录或子目录：子目录经 rel 参数访问，走的是
	// 各端点内部已有的路径逃逸校验，不需要在闸门这一层多开一个口子。
	if root := s.scratchRoot(); root != "" && want == root {
		return root, true
	}
	if s.mgr == nil {
		// 闸门坏了要关上：读不出位置表时拒绝而不是放行
		s.log.Error("工作树白名单：manager 未注入，按拒绝处理")
		return "", false
	}
	locs, err := s.mgr.ListProjectLocations()
	if err != nil {
		// 读不出位置表时**拒绝**而不是放行：闸门坏了要关上，不能敞开
		s.log.Error("工作树白名单：查询位置表失败，按拒绝处理", "cause", err)
		return "", false
	}
	for _, l := range locs {
		if l.ProjectID == "" {
			continue
		}
		if filepath.Clean(l.Path) == want {
			return want, true
		}
	}
	managedRoot := filepath.Join(s.conf().DataDir, "worktrees")
	for _, l := range locs {
		if l.ProjectID == "" {
			continue
		}
		ws, probeErr := workspace.ProbeWorkspaces(ctx, l.Path, managedRoot)
		if probeErr != "" {
			continue
		}
		for _, w := range ws {
			if filepath.Clean(w.Path) == want {
				return want, true
			}
		}
	}
	return "", false
}

