n_agentd_Server_startRoomAttachRefresh.signature:
// startRoomAttachRefresh asynchronously resolves remote task workdirs. A single
// refresh is shared by concurrent list requests and throttled between passes.
func (s *Server) startRoomAttachRefresh(links []ledger.TaskLink) {
	remoteLinks := make(map[string]ledger.TaskLink)
	for _, link := range links {
		if link.Target == "" {
			continue
		}
		remoteLinks[roomAttachCacheKey(link)] = link
	}
	if len(remoteLinks) == 0 {
		return
	}

	s.roomAttachMu.Lock()
	now := time.Now()
	if s.roomAttachRefreshing || (!s.roomAttachLastRefresh.IsZero() &&
		now.Sub(s.roomAttachLastRefresh) < roomAttachRefreshInterval) {
		s.roomAttachMu.Unlock()
		return
	}
	s.roomAttachRefreshing = true
	s.roomAttachLastRefresh = now
	s.roomAttachMu.Unlock()

	go func() {
		defer func() {
			s.roomAttachMu.Lock()
			s.roomAttachRefreshing = false
			s.roomAttachMu.Unlock()
		}()

		ctx, cancel := context.WithTimeout(context.Background(), roomAttachBackgroundTimeout)
		defer cancel()
		workers := make(chan struct{}, roomAttachRefreshWorkers)
		var wg sync.WaitGroup
		for _, link := range remoteLinks {
			link := link
			wg.Add(1)
			go func() {
				defer wg.Done()
				select {
				case workers <- struct{}{}:
				case <-ctx.Done():
					s.log.Warn("房间 attach 后台刷新取消", "target", link.Target,
						"task", link.TaskID, "cause", ctx.Err())
					return
				}
				defer func() { <-workers }()
				attach, err := s.lookupRoomAttach(ctx, link, nil)
				if err != nil {
					s.invalidateRoomAttach(link)
					s.log.Warn("房间 attach 后台刷新失败", "target", link.Target,
						"task", link.TaskID, "cause", err)
					return
				}
				s.storeRoomAttach(link, attach)
				s.log.Info("房间 attach 后台刷新成功", "target", link.Target,
					"task", link.TaskID, "workdir", attach.WorkDir)
			}()
		}
		wg.Wait()
		s.log.Info("房间 attach 后台刷新完成", "links", len(remoteLinks),
			"timed_out", ctx.Err() != nil)
	}()
}

n_agentd_Server_storeRoomAttach.signature:
func (s *Server) storeRoomAttach(link ledger.TaskLink, attach *proto.RoomAttach) {
	copy := *attach
	s.roomAttachMu.Lock()
	if s.roomAttachCache == nil {
		s.roomAttachCache = make(map[string]roomAttachCacheEntry)
	}
	s.roomAttachCache[roomAttachCacheKey(link)] = roomAttachCacheEntry{
		attach: &copy, expiresAt: time.Now().Add(roomAttachCacheTTL),
	}
	s.roomAttachMu.Unlock()
}

n_agentd_Server_taskOrErr.signature:
// taskOrErr 读取路径中的任务并做门禁：任务不存在写 404、缺工作区路径写 400，
// 两种情况都返回 ok=false（调用方直接 return 即可）。
//
// 为什么独立于 taskRepoOrErr：diff / branches 两个端点除了工作区路径还要读
// 任务的 BaseCommit（B65），而另外三个调用点只关心路径。拆开后既不动它们的
// 签名，也不必让它们承担一个用不到的返回值。
//
// 返回的是 task.Workdir() 而非 task.RepoPath（为什么 diff/fetch/run 必须在
// Workdir 而非主仓库：worktree 任务的 executor cwd 与分支 HEAD 都在 Workdir，
// 主仓库的 HEAD 停在派发前的位置——diff 相对基准、fetch 看工作区文件、run 跑
// 测试都必须落在 executor 真正干活的目录，否则审阅的是错误的代码状态）。
//
// 供 diff/fetch/run 三条审阅路由共用——它们只关心任务指向的仓库，不依赖状态机。
func (s *Server) taskOrErr(w http.ResponseWriter, taskID string) (*proto.Task, bool) {
	if s.mgr == nil {
		s.log.Warn("任务读取路径到达但 manager 未注入", "task", taskID)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return nil, false
	}
	task, err := s.mgr.GetTask(taskID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			s.log.Warn("任务不存在", "task", taskID)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "任务不存在"})
		} else {
			s.log.Error("读取任务失败", "task", taskID, "cause", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		}
		return nil, false
	}
	if task.Workdir() == "" {
		s.log.Warn("任务缺少工作区路径", "task", taskID)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "任务没有工作区路径"})
		return nil, false
	}
	return task, true
}

