		st := proto.MachineStatus{Name: name}
		if ts, ok := fetched[name]; ok {
			st.Ok = true
			st.FetchedAt = ts
		} else {
			// 「没有快照」不等于「不可达」：可能是它上面根本没有任务，或镜像
			// 还没跑到它。报文必须把两种可能都说出来，不能武断写成「不可达」
			st.Ok = false
			st.Error = "尚无该机器的镜像快照（可能从未可达，或它上面没有任务）"
		}
		machines = append(machines, st)
	}

	s.log.Info("任务汇总完成", "local", len(tasks), "mirrored", len(mirrors),
		"machines", len(machines))
	return proto.TasksResp{Machines: machines, Tasks: views}
}

n_agentd_Server_ticketDestructive.signature:
// ticketDestructive 判定工单是否属「破坏性/不可逆/外部可见」类（既有硬纪律的机械
// 代理，D-destructive 台账 L10）：该工单 task 事件流存在 approver_decision 事件
// （ticket_id 匹配且 decision ∈ {escalate, error}）——审批者不敢放行或裁决失败即
// 系统标记的危险请求。窗口用 recentEventsLimit=100（server.go:65，与任务详情同款）。
func (s *Server) ticketDestructive(taskID, ticketID string) bool {
	if s.mgr == nil {
		// 读不出就保守：不标破坏性，避免在 manager 未就绪时误判
		return false
	}
	events, err := s.mgr.EventsFrom(taskID, 0, recentEventsLimit)
	if err != nil {
		return false
	}
	for _, ev := range events {
		if ev.Type != proto.EventTypeApproverDecision {
			continue
		}
		var p orchestration.ApproverDecisionPayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			continue
		}
		if p.TicketID == ticketID && (p.Decision == "escalate" || p.Decision == "error") {
			return true
		}
	}
	return false
}

