n_agentd_Server_triggerRestart.signature:
// triggerRestart 触发优雅关停。restart 未注入时只打日志——这只可能发生在
// 测试或 bootstrap 顺序出错时，静默返回会让「换版成功但永远不重启」变成
// 一个查不出根因的现象。
func (s *Server) triggerRestart(reason string) {
	if s.restart == nil {
		s.log.Error("换版后无法触发重启：restart 未注入", "reason", reason)
		return
	}
	if !s.restart(reason) {
		s.log.Warn("触发重启：已在关停中，本次触发被忽略", "reason", reason)
	}
}

n_agentd_Server_workspaceRootOrErr.signature:
// workspaceRootOrErr 取出并校验 path 查询参数，失败时已写好响应。
//
// 返回 ok=false 时调用方必须直接 return。
func (s *Server) workspaceRootOrErr(w http.ResponseWriter, r *http.Request) (string, bool) {
	path := r.URL.Query().Get("path")
	if path == "" {
		s.log.Warn("工作树请求缺 path 参数", "url_path", r.URL.Path)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "缺少 path 参数"})
		return "", false
	}
	root, ok := s.resolveWorkspace(r.Context(), path)
	if !ok {
		// 400 而不是 403：白名单是**参数校验**，不是安全边界。控制台会话在
		// 能力上等价于主令牌（auth 中间件让两者落在同一个 mux 上，其中包含
		// POST /api/tasks/{id}/run 的 sh -c），所以这里挡不住任何有心人，
		// 它挡的是「前端传了个打错的路径，把 agentd 变成任意目录浏览器」。
		// 403 会宣称一个不存在的权限模型，误导排障的人往鉴权方向找。
		// 完整论证见 docs/superpowers/specs/2026-08-12-w4-pty-terminal-design.md §1
		s.log.Warn("工作树白名单拒绝", "path", path, "url_path", r.URL.Path)
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": "路径不是本机已探测到的工作树，拒绝访问"})
		return "", false
	}
	return root, true
}

n_agentd_Server_writeDispatchError.signature:
// writeDispatchError 把 dispatch 失败映射为 HTTP 状态码与可读原因（P1-14）。
//
// 映射规则：
//   - ErrDirtyWorktree → 409：工作区状态与服务端要求冲突，这是最常见的拒绝原因，
//     协调者一条 git 命令即可修复——必须带可读 reason（err.Error() 含脏文件第一行），
//     而非扁平化的「派发任务失败」
//   - ErrWorkdirBusy → 409：目标工作目录已被一个非终态任务占用（含 waiting_review），
//     与 ErrDirtyWorktree 同为状态冲突而非请求错误——报文点名占用任务并给出
//     两条出路（done/stop 它，或改用 --new-worktree）
//   - ErrBaseCommitMissing → 400：任务仓库落后于协调者本地基线，拒发并带 git push
//     动作提示；与参数类错误同层级——调用方先解决远程仓库再重派
//   - workspace.ErrRepoUnusable / ErrBadDispatchRequest / workspace.ErrBadWorkspaceReq → 400：调用方先
//     解决请求本身的问题（仓库路径不对、参数缺失/互斥/分支不存在、plan 编码错误）
//   - ErrProjectNotRegistered → 400：project_id / project_name 在本机位置表里查不到，
//     报文自带本机已登记清单——协调者拿到即可行动（换名字，或先 handoff project add）；
//     本机 CLI 收到这条会自动补登记后重发（B62）
//   - ErrExecutorStartFailed → 500 + 可读真因：executor 启动失败（执行者二进制不在 PATH、
//     opencode 未安装等）是环境问题而非 agentd 内部故障——响应体直接带
//     err.Error()（含真因如 exec: "opencode": executable file not found），协调者拿到
//     即可行动（装依赖），不必去 agentd.log 翻一行 exec 错误
//   - ErrEnvResolveFailed → 500 + 可读真因：env 文件缺失/语法错是执行机上的配置
//     问题，响应体带完整路径与行号，派发者改完文件重派即可
//   - 其余（任务目录/落库等 agentd 侧故障）→ 500
func (s *Server) writeDispatchError(w http.ResponseWriter, projectRef string, err error) {
	switch {
	case errors.Is(err, orchestration.ErrWorkspaceUnavailable):
		s.log.Error("dispatch 失败：工作区能力未注入", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrDirtyWorktree):
		s.log.Warn("dispatch 被拒：工作区不干净", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, orchestration.ErrWorkdirBusy):
		s.log.Warn("dispatch 被拒：目标工作目录被占用", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrFetchRefLockContention):
		s.log.Warn("dispatch 被拒：基线补拉遭遇远端 ref 锁竞争", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrLocalBaseBranchDiverged):
		s.log.Warn("dispatch 被拒：本地工作分支与 origin 分叉", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrBaseCommitMissing):
		s.log.Warn("dispatch 被拒：任务仓库落后于本地基线", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrRepoUnusable):
		s.log.Warn("dispatch 被拒：仓库不可用", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrProjectNotRegistered):
		s.log.Warn("dispatch 被拒：项目未登记", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrBadDispatchRequest):
		s.log.Warn("dispatch 被拒：请求参数非法", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrBadWorkspaceReq):
		s.log.Warn("dispatch 被拒：工作区参数非法", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, errReceiverNotCarrierMachine):
		s.log.Warn("dispatch 被拒：接收机不是载体登记机", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, scheduling.ErrNoDefault), errors.Is(err, scheduling.ErrNotFound),
		errors.Is(err, scheduling.ErrInvalid), errors.Is(err, scheduling.ErrNoHealthy),
		errors.Is(err, scheduling.ErrRoleMismatch):
		s.log.Warn("dispatch 被拒：接收者/编制参数", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, scheduling.ErrNameConflict), errors.Is(err, scheduling.ErrPhysicalOverride),
		errors.Is(err, scheduling.ErrNoSlot), errors.Is(err, scheduling.ErrRetryExhausted):
		s.log.Warn("dispatch 被拒：接收者冲突或满员", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, orchestration.ErrNoProcHeadroom):
		s.log.Warn("dispatch 被拒：进程余量不足", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, orchestration.ErrExecutorStartFailed):
		s.log.Error("dispatch 启动 executor 失败（环境问题，真因回显）", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
	case errors.Is(err, orchestration.ErrEnvResolveFailed):
		s.log.Error("dispatch 被拒：env 文件解析失败（配置问题，真因回显）", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
	case errors.Is(err, orchestration.ErrDisciplineResolveFailed):
		s.log.Error("dispatch 被拒：纪律块解析失败（配置问题，真因回显）", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
	default:
		s.log.Error("派发任务失败", "project", projectRef, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "派发任务失败"})
	}
}

n_agentd_Server_writeEntryError.signature:
// writeEntryError 把条目操作/查找的错误映射成 HTTP 应答（四个 entry 端点 +
// search 端点共用）。
//
// 文案策略与写文件端点同一纪律：被拒的哨兵错误（workspace.ErrEntryExists /
// workspace.ErrEntryNotFound / workspace.ErrBadEntryName / workspace.ErrPathEscape / workspace.ErrGitDirWrite）**原样透传
// err.Error()**——这些哨兵文案本身就带目标细节（如「不允许写入 .git 目录:
// ".git"」），吞成「操作失败」只会让用户回来问。4xx 一律 Warn（被拒不是 agentd
// 出故障），5xx 才 Error。
func (s *Server) writeEntryError(w http.ResponseWriter, root, rel string, err error) {
	switch {
	case errors.Is(err, workspace.ErrEntryExists):
		s.log.Warn("工作树条目操作被拒：目标已存在", "root", root, "rel", rel, "status", http.StatusConflict)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrEntryNotFound), errors.Is(err, fs.ErrNotExist):
		s.log.Warn("工作树条目操作被拒：目标不存在", "root", root, "rel", rel, "status", http.StatusNotFound)
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrBadEntryName):
		s.log.Warn("工作树条目操作被拒：名字不合法", "root", root, "rel", rel, "status", http.StatusBadRequest)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrPathEscape):
		s.log.Warn("工作树条目操作被拒：路径逃逸", "root", root, "rel", rel, "status", http.StatusBadRequest)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrGitDirWrite):
		s.log.Warn("工作树条目操作被拒：命中 .git", "root", root, "rel", rel, "status", http.StatusBadRequest)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	default:
		s.log.Error("工作树条目操作失败", "root", root, "rel", rel, "status", http.StatusInternalServerError, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "操作失败"})
	}
}

n_agentd_Server_writeManagerError.signature:
// writeManagerError 把 manager 返回的错误映射为 HTTP 状态码与提示。
//
// 映射规则：store.ErrNotFound → 404；store.ErrBadTransit → 409（状态不允许）；
// executor.ErrTaskNotRunning → 409（executor 运行态已丢失，agentd 可能重启过，
// 需重新派发——可行动提示而非扁平 500）；其余 → 500。
func (s *Server) writeManagerError(w http.ResponseWriter, taskID, op string, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		s.log.Warn("manager 操作目标任务不存在", "task", taskID, "op", op)
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "任务不存在"})
	case errors.Is(err, store.ErrBadTransit):
		s.log.Warn("manager 操作状态不允许", "task", taskID, "op", op, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": "任务当前状态不允许该操作"})
	case errors.Is(err, executor.ErrTaskNotRunning):
		// 为什么映射 409 而非 500：executor 运行态随 agentd 重启（或进程死亡）丢失，
		// 是「可预期、可行动」的状态而非内部故障——协调者需要的是「重新派发」的
		// 明确指引，而不是被扁平 500 挡在门外（resume 的 executor_gone=false 已表明
		// 会话上下文还在，缺的只是恢复路径）
		s.log.Warn("manager 操作遇执行器运行态已丢失", "task", taskID, "op", op, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": "任务执行器运行态已丢失（agentd 可能重启过），请重新派发"})
	default:
		s.log.Error("manager 操作失败", "task", taskID, "op", op, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
	}
}

n_agentd_Server_writeProjectError.signature:
// writeProjectError 把项目登记操作的失败映射为 HTTP 状态码与可读原因。
//
// 映射规则（与 writeDispatchError 同一套哲学：调用方拿到就能行动）：
//   - store.ErrNotFound → 404：登记名不存在
//   - ErrProjectAlreadyExists → 409：项目/名字/路径已被占用，或克隆落点已存在——
//     与 ErrDirtyWorktree/ErrWorkdirBusy 同为状态冲突
//   - store.ErrProjectDuplicate → 409：改名/改路径撞上已被占用的名字或路径
//     （handleProjectPatch 直接透传 store 的冲突哨兵，映射集中在这一处）
//   - ErrWorkdirBusy → 409：注销时项目仓库仍被活跃任务占用
//   - ErrProjectOriginMismatch → 400：路径上是另一个项目——报文同时给出两边
//     的 origin，人一眼就能看出「你说的是 A，那儿实际是 B」
//   - workspace.ErrRepoUnusable / ErrBadDispatchRequest → 400：请求本身的问题
//     （路径不是仓库、没有 origin、clone 失败、参数缺失）
//   - 其余 → 500
func (s *Server) writeProjectError(w http.ResponseWriter, name string, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		s.log.Warn("项目登记操作被拒：登记不存在", "name", name, "cause", err)
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrProjectAlreadyExists):
		s.log.Warn("项目登记操作被拒：已存在", "name", name, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, store.ErrProjectDuplicate):
		s.log.Warn("项目登记操作被拒：名字或路径已被占用", "name", name, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, orchestration.ErrWorkdirBusy):
		s.log.Warn("项目登记操作被拒：被活跃任务占用", "name", name, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrProjectOriginMismatch):
		s.log.Warn("项目登记被拒：路径上是另一个项目", "name", name, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrRepoUnusable), errors.Is(err, workspace.ErrBadDispatchRequest):
		s.log.Warn("项目登记操作被拒：请求非法", "name", name, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	default:
		s.log.Error("项目登记操作失败", "name", name, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "项目登记操作失败"})
	}
}

n_agentd_coordinatorAttachInfo.signature:
// coordinatorAttachInfo 将 keystone 定位器的结果投影到 agentd wire DTO。
// 不修改服务端返回值、不拼接命令；命令仍由 locator 产生，Machine 为空串仍表示本机。
