n_agentd_decisionTitle.signature:
// decisionTitle 收件箱 decision 条目标题 = 裁决正文首行（简报六段的第一段是「一句话」）。
func decisionTitle(d ledger.Decision) string {
	body := strings.TrimSpace(d.Body)
	if i := strings.IndexByte(body, '\n'); i >= 0 {
		body = body[:i]
	}
	if n := len([]rune(body)); n > 80 {
		return string([]rune(body)[:80]) + "…"
	}
	return body
}

n_agentd_parseForce.signature:
// parseForce 解析 resume 的 force 查询参数。
//
// 为什么自己解析而不用 strconv.ParseBool 的错误：非法值（如 force=yes）一律
// 按 false 处理——强制收口是绕过正常流程的动作，看不懂的输入必须走保守的那边。
func parseForce(r *http.Request) bool {
	switch r.URL.Query().Get("force") {
	case "true", "1":
		return true
	}
	return false
}

